import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import { Link, useSearchParams } from 'react-router-dom';
import { formatDistanceToNow } from 'date-fns';

const Messages = () => {
  const { user } = useAuth();
  const [searchParams] = useSearchParams();
  const [conversations, setConversations] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const messagesEndRef = useRef(null);

  // ✅ Check if user parameter is in URL (from profile)
  const userIdFromUrl = searchParams.get('user');

  useEffect(() => {
    fetchConversations();
  }, []);

  useEffect(() => {
    // ✅ If user ID in URL, fetch that user's messages
    if (userIdFromUrl) {
      fetchUserAndMessages(userIdFromUrl);
    }
  }, [userIdFromUrl]);

  useEffect(() => {
    if (selectedUser) {
      fetchMessages(selectedUser._id);
    }
  }, [selectedUser]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const fetchUserAndMessages = async (userId) => {
    try {
      const res = await axios.get(`http://localhost:5000/api/users/${userId}`);
      setSelectedUser(res.data);
      await fetchMessages(userId);
    } catch (err) {
      console.error('Error fetching user:', err);
    }
  };

  const fetchConversations = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/messages/conversations/all');
      setConversations(res.data);
      setLoading(false);
      
      // If no user from URL, select first conversation
      if (!userIdFromUrl && res.data.length > 0) {
        setSelectedUser(res.data[0].user);
      }
    } catch (err) {
      console.error('Error fetching conversations:', err);
      setLoading(false);
    }
  };

  const fetchMessages = async (userId) => {
    try {
      const res = await axios.get(`http://localhost:5000/api/messages/${userId}`);
      setMessages(res.data);
    } catch (err) {
      console.error('Error fetching messages:', err);
    }
  };

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim() || !selectedUser) return;

    setSending(true);
    try {
      const res = await axios.post('http://localhost:5000/api/messages', {
        receiverId: selectedUser._id,
        content: newMessage.trim()
      });
      
      setMessages([...messages, res.data]);
      setNewMessage('');
    } catch (err) {
      console.error('Error sending message:', err);
      alert('Failed to send message');
    }
    setSending(false);
  };

  if (loading) return <div className="loading">Loading messages...</div>;

  return (
    <div className="messages-container">
      <div className="messages-sidebar">
        <h3>💬 Messages</h3>
        {conversations.length === 0 ? (
          <p className="no-conversations">No conversations yet</p>
        ) : (
          conversations.map((conv) => (
            <div 
              key={conv.user._id}
              className={`conversation-item ${selectedUser?._id === conv.user._id ? 'active' : ''}`}
              onClick={() => setSelectedUser(conv.user)}
            >
              <img 
                src={conv.user.profilePicture ? `http://localhost:5000${conv.user.profilePicture}` : 'https://ui-avatars.com/api/?name=' + encodeURIComponent(conv.user.name || conv.user.username) + '&background=1877f2&color=fff&size=40'} 
                alt={conv.user.username}
                onError={(e) => {
                  e.target.src = 'https://ui-avatars.com/api/?name=' + encodeURIComponent(conv.user.name || conv.user.username) + '&background=1877f2&color=fff&size=40';
                }}
              />
              <div>
                <strong>{conv.user.name || conv.user.username}</strong>
                <p className="last-message">
                  {conv.lastMessage?.content?.substring(0, 30)}
                  {conv.lastMessage?.content?.length > 30 && '...'}
                </p>
              </div>
              {conv.unread && <span className="unread-badge">●</span>}
            </div>
          ))
        )}
      </div>

      <div className="messages-chat">
        {selectedUser ? (
          <>
            <div className="chat-header">
              <Link to={`/profile/${selectedUser._id}`}>
                <img 
                  src={selectedUser.profilePicture ? `http://localhost:5000${selectedUser.profilePicture}` : 'https://ui-avatars.com/api/?name=' + encodeURIComponent(selectedUser.name || selectedUser.username) + '&background=1877f2&color=fff&size=40'} 
                  alt={selectedUser.username}
                  onError={(e) => {
                    e.target.src = 'https://ui-avatars.com/api/?name=' + encodeURIComponent(selectedUser.name || selectedUser.username) + '&background=1877f2&color=fff&size=40';
                  }}
                />
                <span>{selectedUser.name || selectedUser.username}</span>
              </Link>
            </div>

            <div className="chat-messages">
              {messages.length === 0 ? (
                <p className="no-messages">No messages yet. Start a conversation!</p>
              ) : (
                messages.map((msg) => (
                  <div 
                    key={msg._id}
                    className={`message ${msg.sender._id === user.id ? 'sent' : 'received'}`}
                  >
                    <div className="message-content">
                      <p>{msg.content}</p>
                      <span className="message-time">
                        {formatDistanceToNow(new Date(msg.createdAt), { addSuffix: true })}
                      </span>
                    </div>
                  </div>
                ))
              )}
              <div ref={messagesEndRef} />
            </div>

            <form onSubmit={sendMessage} className="chat-input">
              <input
                type="text"
                placeholder={`Message ${selectedUser.name || selectedUser.username}...`}
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
              />
              <button type="submit" disabled={sending}>
                {sending ? '...' : 'Send'}
              </button>
            </form>
          </>
        ) : (
          <div className="no-chat-selected">
            <p>Select a conversation to start messaging</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Messages;
